def counted_case_document():
    """The twenty-sixth file: landing R4's readings and spellings, each with its answer."""
    readings = {}
    for name in sorted(COUNTED_READINGS):
        member, text, mark, unit, why = COUNTED_READINGS[name]
        readings[name] = {
            "member": member, "text": text, "mark": mark, "unit": unit, "why": why,
            "answer": counted_reading(member, text, mark, _COUNTED_UNITS[unit]),
        }
    spellings = {}
    for name in sorted(COUNTED_SPELLINGS):
        member, iso, form, contact, why = COUNTED_SPELLINGS[name]
        spellings[name] = {
            "member": member, "iso": iso, "form": form, "contact": contact, "why": why,
            "answer": counted_spelling(member, iso, form, contact),
        }
    for name in sorted(COUNTED_ANCHORS):
        found = readings[name] if name in readings else spellings[name]
        if found["answer"] != COUNTED_ANCHORS[name]:
            raise SystemExit(f"the oracle misses its calendar anchor {name}: {found['answer']}")
    dealings = {}
    for name in sorted(COUNTED_DEALINGS):
        census, dated, why = COUNTED_DEALINGS[name]
        dealings[name] = {
            "census": census, "dated": dated, "why": why,
            "answer": counted_contacts(census, dated),
        }
    keepings = {}
    for name in sorted(COUNTED_KEEPINGS):
        ordinals, lows, highs, day, holes, why = COUNTED_KEEPINGS[name]
        keepings[name] = {
            "ordinals": ordinals, "lows": lows, "highs": highs, "day": day, "holes": holes,
            "grid": 0, "why": why,
            "answer": counted_days_kept_off(ordinals, lows, highs, day, set(holes)),
        }
    for name in sorted(COUNTED_GRID_KEEPINGS):
        ordinals, lows, highs, day, holes, grid, why = COUNTED_GRID_KEEPINGS[name]
        keepings[name] = {
            "ordinals": ordinals, "lows": lows, "highs": highs, "day": day, "holes": holes,
            "grid": grid, "why": why,
            "answer": counted_days_kept_off(ordinals, lows, highs, day, set(holes), grid),
        }
    holes = {member: list(counted_hole_words(member)) for member in sorted(COUNTED_SYSTEMS)}
    moment_holes = {
        member: list(counted_hole_words(member, True)) for member in sorted(COUNTED_SYSTEMS)
    }
    reaches = {}
    for name in sorted(COUNTED_REACHES):
        member, written, tail, boundary, low_side, edge, why = COUNTED_REACHES[name]
        at = unit_ordinal(boundary, tail, "local")
        reaches[name] = {
            "member": member, "written": written, "tail": tail, "boundary": boundary,
            "low_side": low_side, "edge": edge, "why": why,
            "answer": counted_reach(
                member, _COUNTED_UNITS[written], COUNTED_TAIL_SECONDS[tail], at, low_side, edge
            ),
        }
    islands = {}
    for name in sorted(COUNTED_ISLANDS):
        member, written, tail, boundary, low_side, edge, why = COUNTED_ISLANDS[name]
        at = unit_ordinal(boundary, tail, "local")
        reach = counted_reach(
            member, _COUNTED_UNITS[written], COUNTED_TAIL_SECONDS[tail], at, low_side, edge
        )
        islands[name] = {
            "member": member, "written": written, "tail": tail, "boundary": boundary,
            "low_side": low_side, "edge": edge, "why": why,
            "answer": {
                "reach": reach,
                "islands": [list(pair) for pair in counted_islands(
                    member, _COUNTED_UNITS[written], COUNTED_TAIL_SECONDS[tail], at, low_side, reach
                )],
            },
        }
    steps = {}
    for name in sorted(COUNTED_STEPS):
        distance, pairs, reach, why = COUNTED_STEPS[name]
        steps[name] = {
            "distance": distance, "islands": [list(pair) for pair in pairs], "reach": reach,
            "why": why, "answer": counted_off_islands(distance, pairs, reach),
        }
    strata = {}
    for name in sorted(COUNTED_STRATA):
        near, far, pairs, reach, why = COUNTED_STRATA[name]
        widened_near, widened_far = counted_strata_off_islands(near, far, pairs, reach)
        strata[name] = {
            "near": near, "far": far, "islands": [list(pair) for pair in pairs], "reach": reach,
            "why": why, "answer": {"near": widened_near, "far": widened_far},
        }
    return {
        "what": "Method section G7.10's two halves (landing R4, plan P4-D384), each case with "
        "its answer computed from the method's text with datetime and Fraction: a count read "
        "as the moment its system names, written as ISO text at a unit, and a moment written "
        "back as its system's count, spelled as a `count_form` says; the contact numbers "
        "a census deals over the dated cells of an Epic column; the days each system's "
        "column of dates, and of moments, holds no date on; how far a tail reaches short "
        "of a wall of them, the islands inside that reach, a tail's end and group stepped "
        "off one and every stratum lying wholly on one given room; and the twin's ranks "
        "kept off them, by whole days or by the unit the column is written at.",
        "dealings": dealings,
        "holes": holes,
        "islands": islands,
        "keepings": keepings,
        "moment_holes": moment_holes,
        "reaches": reaches,
        "generated_by": "tools/reference/make_generation_reference_vectors.py",
        "method": "docs/spec/generation-method-v1.md",
        "never_imports": ["synthtwin", "numpy", "pandas"],
        "readings": readings,
        "spellings": spellings,
        "steps": steps,
        "strata": strata,
    }


# -- G7.3i, the joint day plan (landing 3b.3, plan P4-D368) --------------


def day_census_of(days, starts, bins=34, bin_of=None):
    """A census of these days in groups starting at the bins `starts` (bins
    from 1 for the day of the month, 0 for the weekday), each group running
    to the bin before the next start and the last to the last bin."""
    bin_of = bin_of if bin_of is not None else month_bin
    low = 1 if bins == 34 else 0
    top = low + bins - 1
    groups = []
    for index, first in enumerate(starts):
        last = starts[index + 1] - 1 if index + 1 < len(starts) else top
        count = sum(1 for day in days if first <= bin_of(day) <= last)
        groups += [{"first": first, "last": last, "count": count}]
    return groups


def day_weekday_of(day):
    """A day's weekday, Monday nought."""
    return (day + 3) % 7


def day_case(why, real, month_starts, weekday_starts, pins, holes=(), reachable=True):
    """A state of ranks counted in days: the real body `real` ascending, its
    ranks in `pins` pinned at their real days and every other rank drawn
    evenly between the pins either side, as G7.3's construction spreads a
    gap; the two censuses counted from the real body in the groups their
    starts name (no weekday census where `weekday_starts` is empty)."""
    real = sorted(real)
    ordinals = list(real)
    pins = sorted(set(pins) | {0, len(real) - 1})
    for place in range(len(pins) - 1):
        a, b = pins[place], pins[place + 1]
        for rank in range(a + 1, b):
            ordinals[rank] = real[a] + ((rank - a) * (real[b] - real[a])) // (b - a)
    pinned, lows, highs = shared_layout(ordinals, pins)
    return {
        "why": why,
        "ordinals": ordinals,
        "lows": lows,
        "highs": highs,
        "pinned": pinned,
        "body": [0, len(real) - 1],
        "span": [real[0], real[-1]],
        "wanted": len(set(ordinals)),
        "reachable": reachable,
        "census": day_census_of(real, month_starts),
        "weekdays": day_census_of(real, weekday_starts, 7, day_weekday_of) if weekday_starts else [],
        "holes": sorted(holes),
    }


def day_dates(*triples):
    """Day numbers of (year, month, day) triples."""
    return [days_from_civil(year, month, date) for year, month, date in triples]


def day_billing_case():
    """Billing on the 1st and the 15th, no weekday census (rule (b))."""
    heaps = day_dates(*[(2024, month, date) for month in (1, 2, 3) for date in (1, 15) for _ in range(3)])
    spread = [days_from_civil(2024, 1, 2) + 3 * step for step in range(27)]
    real = heaps + spread
    return day_case(
        "Billing from 1 January to 31 March 2024: three rows on each 1st and 15th, twenty-seven "
        "spread three days apart, and no weekday census. The census groups the 1st, the 2nd to "
        "the 14th, the 15th and the 16th to the month's last day; pass A moves the evenly drawn "
        "ranks onto the 1st and the 15th of their own gaps.",
        real, [1, 2, 15, 16], [], [22],
    )


def day_tenth_case():
    """A monthly visit on the 10th beside a weekday census of seven groups."""
    heaps = day_dates(*[(2024, month, 10) for month in range(1, 7) for _ in range(5)])
    spread = day_dates((2024, 1, 3), (2024, 2, 6), (2024, 2, 21), (2024, 3, 12), (2024, 3, 27),
                       (2024, 4, 4), (2024, 4, 18), (2024, 5, 2), (2024, 5, 23), (2024, 6, 14))
    return day_case(
        "A visit on the 10th of each month from January to June 2024, five rows each, and ten "
        "other days, with the weekday census counting each day. Pass A puts the ranks on the "
        "10ths; pass B meets the weekday counts with every move keeping its rank on or off the "
        "10th, so the 10th's count stands.",
        heaps + spread, [1, 10, 11], [0, 1, 2, 3, 4, 5, 6], [20],
    )


def day_month_end_case():
    """Month ends, the last day of each month a bin of its month's length."""
    ends = day_dates((2024, 1, 31), (2024, 1, 31), (2024, 2, 29), (2024, 2, 29), (2024, 2, 29),
                     (2024, 3, 31), (2024, 3, 31), (2024, 4, 30), (2024, 4, 30), (2024, 4, 30),
                     (2024, 5, 31), (2024, 5, 31))
    spread = [days_from_civil(2024, 1, 3) + 5 * step for step in range(30)]
    return day_case(
        "Month ends from January to May 2024 -- the 31st of January, March and May, the 29th of "
        "February and the 30th of April -- beside thirty days spread five apart. The census "
        "counts days 1 to 27, the 28th to the 30th where they are not the last, and the last "
        "day of a 29-, 30- and 31-day month, so a rank put on the month's end goes to that "
        "month's own last day.",
        ends + spread, [1, 28, 31, 32, 33, 34], [], [14, 28],
    )


def day_business_billing_case():
    """Billing on the 1st and 15th rolled to a business day, weekends empty."""
    rolled = []
    for month in (1, 2, 3, 4):
        for date in (1, 15):
            day = days_from_civil(2024, month, date)
            while day_weekday_of(day) >= 5:
                day += 1
            rolled += [day] * 3
    business = [day for day in range(days_from_civil(2024, 1, 2), days_from_civil(2024, 4, 30), 4)
                if day_weekday_of(day) < 5]
    return day_case(
        "Billing from January to April 2024 on the 1st and the 15th rolled to the next business "
        "day, three rows each, beside business days four apart; the weekday census counts "
        "Monday to Friday each and the weekend nought. Pass A keeps off every Saturday and "
        "Sunday, the days of the empty weekday group, so pass B has none to take back.",
        rolled + business, [1, 2, 4, 15, 16, 18], [0, 1, 2, 3, 4, 5], [16],
    )


def day_births_case():
    """Births with a weekend dip and the 1st heaped."""
    firsts = day_dates(*[(2023, month, 1) for month in range(1, 13)])
    spread = [day for day in range(days_from_civil(2023, 1, 2), days_from_civil(2023, 12, 31), 6)
              if day_weekday_of(day) < 5 or day % 3 == 0]
    return day_case(
        "Births through 2023: the 1st of every month, and days six apart with two weekend days in "
        "three left out. The weekday census counts each day; the day-of-month census the 1st, "
        "the 2nd to the 15th and the 16th to the last day.",
        firsts + spread, [1, 2, 16], [0, 1, 2, 3, 4, 5, 6], [20, 40],
    )


def day_form_hole_case():
    """A hole on the 15th the passes keep off."""
    heaps = day_dates(*[(2024, month, 1) for month in (1, 2, 3) for _ in range(4)])
    spread = [day for day in range(days_from_civil(2024, 1, 2), days_from_civil(2024, 3, 31), 3)
              if civil_from_days(day)[2] != 15]
    holes = day_dates((2024, 1, 15), (2024, 2, 15), (2024, 3, 15))
    return day_case(
        "The 1st heaped from January to March 2024 and days three apart, none on a 15th, each "
        "15th a hole of the description: no rank of pass A is put on one, though the 15th "
        "shares its group with the days beside it.",
        heaps + spread, [1, 2], [], [12], holes,
    )


def day_repair_case():
    """The spelling repair keeping the published groups (the Codex review of
    landing 3b.3, item 1): a rank alone on Monday 1 July 2024 whose cell
    wears an absent spelling, the 1st its own group and Monday to Friday
    one weekday group."""
    ordinals = day_dates(
        (2024, 3, 5), (2024, 4, 1), (2024, 6, 10), (2024, 7, 1), (2024, 8, 20), (2024, 11, 11),
    )
    return {
        "why": "A rank alone on Monday 1 July 2024, its cell wearing an absent spelling, moves "
        "to the nearest day of its window that keeps its day-of-month group (the 1st alone) and "
        "its weekday group (Monday to Friday), is no hole and writes no absent spelling, a day "
        "no rank holds as it was alone: not the 2nd (another group), 1 June (a Saturday), 1 "
        "August (its cell absent too), 1 May (a hole) or 1 April (held), but 1 October.",
        "repair": True,
        "ordinals": ordinals,
        "rank": 3,
        "window": day_dates((2024, 1, 1), (2024, 12, 31)),
        "spelled": day_dates((2024, 7, 1), (2024, 8, 1)),
        "census": day_census_of(ordinals, [1, 2]),
        "weekdays": day_census_of(ordinals, [0, 5], 7, day_weekday_of),
        "holes": day_dates((2024, 5, 1)),
    }


def day_repaired(case):
    """G7.3i's spelling repair, from the method's text (the Codex review of
    landing 3b.3, item 1): the day a rank whose cell wears an absent
    spelling moves to, or None. Of the days at most 400 away inside its
    window, no hole, in its day-of-month group and its weekday group,
    whose cell wears no absent spelling, nearest first and the earlier
    first at one distance: the first no rank holds where the rank is alone
    on its day, the first a rank holds where it shares it, else the
    first."""
    days = case["ordinals"]
    origin = days[case["rank"]]
    low, high = case["window"]
    group_of_bin = month_groups_of(case["census"])
    group_of_weekday = [0] * 7
    for index, group in enumerate(case["weekdays"]):
        for weekday in range(group["first"], group["last"] + 1):
            group_of_weekday[weekday] = index

    def keeps(day):
        return (
            low <= day <= high
            and day not in case["holes"]
            and day not in case["spelled"]
            and group_of_bin[month_bin(day) - 1] == group_of_bin[month_bin(origin) - 1]
            and (
                not case["weekdays"]
                or group_of_weekday[(day + 3) % 7] == group_of_weekday[(origin + 3) % 7]
            )
        )

    found = sorted(
        (day for day in range(origin - 400, origin + 401) if day != origin and keeps(day)),
        key=lambda day: (abs(day - origin), day),
    )
    alone = days.count(origin) <= 1
    for day in found:
        if (days.count(day) == 0) == alone:
            return day
    return found[0] if found else None


DAY_STEP_CASES = {
    "day_of_month_billing": day_billing_case,
    "day_of_month_births_dip": day_births_case,
    "day_of_month_business_billing": day_business_billing_case,
    "day_of_month_form_hole": day_form_hole_case,
    "day_of_month_month_end": day_month_end_case,
    "day_of_month_repair": day_repair_case,
    "day_of_month_tenth": day_tenth_case,
}


def day_answer(case):
    """What G7.3i's text makes of one state: every rank's day after both
    passes, or, for a state of the spelling repair, the day its rank takes."""
    if case.get("repair"):
        return day_repaired(case)
    pinned = case["pinned"]
    return day_passes(
        case["ordinals"], case["lows"], case["highs"], pinned, case["body"][0], case["body"][1],
        case["wanted"], case["reachable"], case["census"], case["weekdays"], set(case["holes"]),
        day_empty_weekdays(case["weekdays"], case["span"][0], case["span"][1]),
    )


def day_step_document():
    """The eighteenth file: each state of the joint day plan and its answer."""
    cases = {}
    for name in sorted(DAY_STEP_CASES):
        case = DAY_STEP_CASES[name]()
        case["answer"] = day_answer(case)
        cases[name] = case
    return {
        "what": "The states of ranks counted in days method section G7.3i's joint day plan "
        "(landing 3b.3, plan P4-D368) is frozen on, each with the answer computed from the "
        "method's text: every rank's day after pass A, G7.3f over the day-of-month census's "
        "thirty-four bins with the days of the weekday groups counted nought added to the holes, "
        "and pass B, G7.3f over the weekday census keeping each rank's day-of-month group. A "
        "case states its ranks, their gaps and pins, the body, the span between the two "
        "boundaries, the count of different days to keep where it is reachable, the two "
        "censuses (bins from 1, weekdays from Monday nought) and the holes. A state marked "
        "`repair` is the spelling repair's (the Codex review of landing 3b.3, item 1): the "
        "ranks' days, the rank whose cell wears an absent spelling, its window, the days whose "
        "cell for it wears one (`spelled`), the censuses and the holes; its answer is the day "
        "the rank takes keeping its published groups, or null.",
        "generated_by": "tools/reference/make_generation_reference_vectors.py",
        "method": "docs/spec/generation-method-v1.md",
        "never_imports": ["synthtwin", "numpy", "pandas"],
        "cases": cases,
    }


# -- landing 3b.6's dates that stand out (plan P4-D369), the nineteenth file --
#
# States of G7.3j's plan and draw: the body's knots, the listed dates, the
# holes, the weekday and day-of-month censuses beside the list, the
# budget of new days the parts may open and the new days the count
# leaves the draw, each with the words of its ordinary ranks drawn from a
# fixed generator. Four are stated by hand -- a covered run, two loose
# dates, a listed boundary day, two listed dates with a hole between and
# a rung on the second -- and three are the states the product met on
# three columns, written here as numbers: Monday and Thursday sessions
# over 104 weeks, whose split the census repair moves (the 3b.6
# skeptic's B1); Monday and Thursday sessions with three rows in a
# hundred on any day, whose split the repair moves for the count's new
# days; and six Mays, beside both censuses.

NINETEENTH_BRANCH_PART = "branches-19"


def heavy_case_words(seed, count):
    """`count` words of 64 bits from a fixed generator (Knuth's MMIX
    constants), so a state's draw needs no stream."""
    found = []
    value = seed
    for _step in range(count):
        value = (value * 6364136223846793005 + 1442695040888963407) % TWO64
        found.append(value)
    return found


def heavy_case(name, state):
    """One state with its words, one per ordinary rank of its plan."""
    planned = heavy_plan(
        tuple(tuple(knot) for knot in state["knots"]),
        tuple(tuple(pair) for pair in state["listed"]),
        frozenset(state["holes"]),
        (tuple(tuple(group) for group in state["weekdays"]), tuple(tuple(group) for group in state["month"])),
        state["budget"],
    )
    ordinary = sum(part.count for part in planned[1])
    return dict(state, words=heavy_case_words(len(name), ordinary))


